// Software-Compliance-Prüfung
// baramundi come2gether 2026 Challenge

const endpointItems = $('Windows Endpoints holen').all();
const softwareItems = $('Installierte Software holen').all();

// === KONFIGURATION ===
// Nur diese Software-Titel sind erlaubt (Allowlist)
const allowlist = [
  'Microsoft Office', 'Google Chrome', 'Mozilla Firefox',
  'Microsoft Teams', '7-Zip', 'Notepad++', 'Adobe Acrobat Reader',
  'WinRAR', 'Microsoft Edge'
];

// Diese Software ist verboten (Blocklist)
const blocklist = [
  'BitTorrent', 'uTorrent', 'Vuze',
  'Steam', 'Epic Games', 'Origin',
  'TeamViewer', 'AnyDesk'
];

// Software die nicht in der Allowlist ist, wird als 'nicht genehmigt' gemeldet
// (nur als Info, nicht als Violation)
const flagUnlisted = true;

// Endpoint-Node liefert bereits nur Windows (endpointType=windows)
const windowsEndpoints = endpointItems;

// === Software nach Endpoint gruppieren + deduplizieren ===
const softwareByEndpoint = new Map();
for (const item of softwareItems) {
  const epId = item.json.endpointId || '';
  if (!epId) continue;
  if (!softwareByEndpoint.has(epId)) {
    softwareByEndpoint.set(epId, new Map());
  }
  const swMap = softwareByEndpoint.get(epId);
  const name = item.json.displayName || item.json.name || '';
  if (name && !swMap.has(name)) {
    swMap.set(name, {
      name: name,
      version: item.json.version || '',
      publisher: item.json.publisher || ''
    });
  }
}

// === Analyse pro Endpoint ===
const results = [];

for (const epItem of windowsEndpoints) {
  const epId = epItem.json.id || '';
  const swMap = softwareByEndpoint.get(epId);
  const software = swMap ? Array.from(swMap.values()) : [];

  const ep = {
    id: epId,
    name: epItem.json.displayName || epItem.json.hostName || 'Unbekannt',
    os: epItem.json.operatingSystem || '-',
    software: software,
    violations: []
  };

  // Nur prüfen wenn Software-Daten vorhanden
  if (software.length > 0) {
    // Verbotene Software
    for (const sw of software) {
      if (blocklist.some(b => sw.name.toLowerCase().includes(b.toLowerCase()))) {
        ep.violations.push({
          severity: 'critical',
          software: sw.name, version: sw.version,
          message: 'Verbotene Software: ' + sw.name
        });
      }
    }

    // Nicht genehmigte Software (nicht in Allowlist)
    if (flagUnlisted) {
      for (const sw of software) {
        const isAllowed = allowlist.some(a => sw.name.toLowerCase().includes(a.toLowerCase()));
        const isBlocked = blocklist.some(b => sw.name.toLowerCase().includes(b.toLowerCase()));
        if (!isAllowed && !isBlocked) {
          ep.violations.push({
            severity: 'warning',
            software: sw.name, version: sw.version,
            message: 'Nicht genehmigte Software: ' + sw.name
          });
        }
      }
    }
  }

  results.push(ep);
}

// === Statistik ===
const totalEndpoints = results.length;
const compliant = results.filter(r => r.violations.length === 0).length;
const withViolations = totalEndpoints - compliant;
const criticalCount = results.reduce((s, r) =>
  s + r.violations.filter(v => v.severity === 'critical').length, 0);
const warningCount = results.reduce((s, r) =>
  s + r.violations.filter(v => v.severity === 'warning').length, 0);

return {
  json: {
    results,
    stats: { totalEndpoints, compliant, withViolations, criticalCount, warningCount },
    hasViolations: withViolations > 0
  }
};

const { results, stats } = $input.first().json;
const now = new Date().toLocaleString('de-DE', { year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit' });

const severityColors = {
  critical: { bg:'#fce4ec', border:'#c62828', text:'#c62828', label:'Kritisch' },
  warning:  { bg:'#fff8e1', border:'#f57f17', text:'#f57f17', label:'Warnung' },
  ok:       { bg:'#e8f5e9', border:'#2e7d32', text:'#2e7d32', label:'Konform' }
};

const violationRows = results.filter(ep => ep.violations.length > 0)
  .flatMap(ep => ep.violations.map(v => {
    const c = severityColors[v.severity];
    return '<tr><td style="font-weight:500;">' + ep.name + '</td><td>' + ep.os + '</td><td><span style="background:' + c.bg + ';color:' + c.text + ';padding:3px 10px;border-radius:4px;font-size:12px;font-weight:600;border-left:3px solid ' + c.border + ';">' + c.label + '</span></td><td>' + v.software + '</td><td>' + v.version + '</td><td>' + v.message + '</td></tr>';
  })).join('');

const compliantRows = results.filter(ep => ep.violations.length === 0)
  .map(ep => {
    var swCount = ep.software ? ep.software.length : 0;
    var detail = swCount > 0 ? swCount + ' Programme geprüft — alle genehmigt' : 'Keine Software-Daten vorhanden';
    return '<tr><td style="font-weight:500;">' + ep.name + '</td><td>' + ep.os + '</td><td><span style="background:#e8f5e9;color:#2e7d32;padding:3px 10px;border-radius:4px;font-size:12px;font-weight:600;border-left:3px solid #2e7d32;">Konform</span></td><td colspan="3" style="color:#888;">' + detail + '</td></tr>';
  }).join('');

